  initialCostDecimal: number;
  /** If true, skip market data validation and allow currentPrice=0 */
  isCustom: boolean;
  /** Optional: Unix timestamp (0 = not set, use current time) */
  purchaseDate: number;
  /** User's input unit ("mace", "tael", "kg", "oz", "gram") */
  purchaseUnit: string;
