    if (message.isCustom !== false) {
      writer.uint32(216).bool(message.isCustom);
    }
    if (message.userId !== 0) {
      writer.uint32(224).int32(message.userId);
    }
    if (message.priceUpdatedAt !== 0) {
      writer.uint32(232).int64(message.priceUpdatedAt);
    }
    return writer;
